35	/** Bigram (Dice coefficient) similarity — used to surface a single
36	 *  "Did you mean…" pill when nothing matched as a substring. Catches
37	 *  typos like "wagh bkri" → "wagh bakri" without flooding the user
38	 *  with low-quality matches. */
39	function similarity(a: string, b: string): number {
40	  const la = a.toLowerCase().replace(/[^a-z0-9]/g, '');
41	  const lb = b.toLowerCase().replace(/[^a-z0-9]/g, '');
42	  if (la === lb) return 1;
43	  if (la.length < 2 || lb.length < 2) return 0;
44	  const bg = (s: string) => {
45	    const out = new Set<string>();
46	    for (let i = 0; i < s.length - 1; i++) out.add(s.slice(i, i + 2));
47	    return out;
48	  };
49	  const A = bg(la);
50	  const B = bg(lb);
51	  let inter = 0;
52	  for (const x of A) if (B.has(x)) inter++;
53	  return (2 * inter) / (A.size + B.size);
54	}
