17	} from '../../../design';
18	import { addReceivedQty, findOpenItemByBarcode, OrderItem } from '../../../db/orders';
19	import { enqueue } from '../../../db/outbox';
20	import { trackExpiry } from '../../../db/expiry';
21	import { findProduct, Product } from '../../../db/products';
22	import { learnBarcode, findOpenItemByProductId } from '../../../db/catalog';
23	import { adjustOnHand, findStock, upsertStock } from '../../../db/stock';
24	import { getSession } from '../../../auth/session';
25	import { useT } from '../../../i18n';
26	import { useTheme } from '../../../theme';
27	import { RootStackParamList } from '../../../navigation/types';
28	import { flushOnce } from '../../../sync/syncService';
29	import { haptic } from '../../../utils/haptics';
30	import { useOrderSession } from '../components/OrderSessionContext';
31	import { DatePickerModal } from '../components/DatePickerModal';
32	import { useKeyboardHeight } from '../../../hooks/useKeyboardHeight';
33	
34	type Props = NativeStackScreenProps<RootStackParamList, 'Receiving'>;
35	
36	/** Format ISO date to DD/MM/YYYY for display */
37	function formatForDisplay(iso: string): string {
38	  try {
39	    const [y, m, d] = iso.split('-');
40	    return `${d}/${m}/${y}`;
41	  } catch {
42	    return iso;
43	  }
44	}
45	
46	/** Convert Date object to ISO date string */
47	function toISO(d: Date): string {
48	  return d.toISOString().split('T')[0];
49	}
50	
51	const QUICK_MONTHS = [
52	  { label: '3 mo', months: 3 },
53	  { label: '6 mo', months: 6 },
54	  { label: '1 yr', months: 12 },
55	  { label: '2 yr', months: 24 },
56	];
57	
58	export function ReceivingScreen({ route, navigation }: Props) {
59	  const t = useT();
60	  const { palette } = useTheme();
61	  const kbHeight = useKeyboardHeight();
62	  const { barcode, productId, productName: paramProductName, unit: paramUnit, packSize: paramPackSize } = route.params;
63	  const orderSession = useOrderSession();
64	  const [product, setProduct] = useState<Product | null>(null);
65	  const [item, setItem] = useState<OrderItem | null>(null);
66	  const [qty, setQty] = useState(1);
67	  const [saving, setSaving] = useState(false);
68	
69	  // Expiry date state — driven by native date picker
70	  const [expiryDateObj, setExpiryDateObj] = useState<Date | null>(null);
71	  const [noExpiry, setNoExpiry] = useState(false);
72	  const [showPicker, setShowPicker] = useState(false);
73	  // Per-pack expiry. Default OFF — most bulk scans share one batch /
74	  // one expiry. When ON, expand a list of N rows so the guard can set
75	  // a different expiry on each pack of the multi-quantity scan.
76	  const [perPackExpiry, setPerPackExpiry] = useState(false);
77	  const [perPackExpiries, setPerPackExpiries] = useState<(Date | null)[]>([]);
78	  const [editingPackIdx, setEditingPackIdx] = useState<number | null>(null);
79	
80	  // Keep the per-pack list in lockstep with qty when the toggle is on.
81	  // Initialise new rows with the bulk expiry so the guard can edit
82	  // only the ones that actually differ.
83	  useEffect(() => {
84	    if (!perPackExpiry) return;
85	    setPerPackExpiries((prev) => {
86	      const n = Math.max(1, Math.floor(qty));
87	      if (prev.length === n) return prev;
88	      const next = [...prev];
89	      while (next.length < n) next.push(expiryDateObj);
90	      while (next.length > n) next.pop();
91	      return next;
92	    });
93	  }, [perPackExpiry, qty, expiryDateObj]);
94	
95	  // Resolved product name: canonical name takes priority over legacy product name
96	  const resolvedName = paramProductName ?? product?.name ?? 'Unknown';
97	  const resolvedUnit = paramUnit ?? product?.unit ?? null;
98	  const resolvedPackSize = paramPackSize ?? null;
99	  const packDisplay =
100	    resolvedPackSize != null && resolvedUnit
101	      ? `${resolvedPackSize} ${resolvedUnit}`
102	      : resolvedUnit ?? null;
103	
104	  useEffect(() => {
105	    (async () => {
106	      setProduct(await findProduct(barcode));
107	      // If we have a productId from catalog, look up order item by product_id
108	      if (productId) {
109	        const byProduct = await findOpenItemByProductId(productId);
110	        setItem(byProduct as OrderItem | null);
111	      } else {
112	        setItem(await findOpenItemByBarcode(barcode));
113	      }
114	    })();
115	  }, [barcode, productId]);
116	
117	  // Auto-fill expiry from last scanned item in the order session
118	  useEffect(() => {
119	    if (orderSession.lastExpiry && !noExpiry && !expiryDateObj) {
120	      setExpiryDateObj(new Date(orderSession.lastExpiry));
121	    }
122	  }, [orderSession.lastExpiry, noExpiry, expiryDateObj]);
123	
124	  const setExact = (n: number) => {
125	    haptic.tap();
126	    setQty(n);
127	  };
128	
129	  const expiryDate = useMemo(() => {
130	    if (noExpiry || !expiryDateObj) return null;
131	    return toISO(expiryDateObj);
132	  }, [expiryDateObj, noExpiry]);
133	
134	  const handleQuickMonth = (months: number) => {
135	    haptic.tap();
136	    const d = new Date();
137	    d.setMonth(d.getMonth() + months);
138	    setExpiryDateObj(d);
139	    setNoExpiry(false);
140	  };
141	
142	  const handlePickerChange = (date: Date) => {
143	    setExpiryDateObj(date);
144	    setNoExpiry(false);
145	  };
146	
147	  /** Standalone receipt path — when no order session is active */
148	  const persistStandalone = async (flagged: boolean) => {
149	    const session = getSession();
150	    // Per-pack expiry: split into N qty=1 receipts so each pack carries
151	    // its own expiry date. Single-expiry path stays as one bulk row.
152	    const receipts: Array<{ id: string; qty: number; expiry: string | null }> = perPackExpiry
153	      ? perPackExpiries.map((d) => ({
154	          id: `rcp_${nanoid(12)}`,
155	          qty: 1,
156	          expiry: d ? toISO(d) : null,
157	        }))
158	      : [{ id: `rcp_${nanoid(12)}`, qty, expiry: expiryDate }];
159	
160	    // The first receipt's id is what we use to link mismatch flags etc.
161	    const id = receipts[0].id;
162	
163	    for (const r of receipts) {
164	      await enqueue('receipt', {
165	        id: r.id,
166	        order_id: item?.order_id ?? null,
167	        order_item_id: item?.id ?? null,
168	        product_id: productId ?? null,
169	        barcode,
170	        product_name: resolvedName,
171	        qty: r.qty,
172	        expiry_date: r.expiry,
173	        flagged,
174	        scanned_at: Date.now(),
175	        performed_by: session?.guardId ?? null,
176	        performed_by_name: session?.guardName ?? null,
177	      });
178	    }
179	
180	    // Barcode learning: if this receipt was resolved via canonical catalog,
181	    // permanently map this barcode to the product_id for auto-resolution.
182	    if (productId && !barcode.startsWith('catalog_')) {
183	      await learnBarcode(barcode, productId, 'scan');
184	      // Also tell the backend to learn it
185	      await enqueue('learn_barcode', {
186	        barcode,
187	        product_id: productId,
188	      }).catch(() => {});
189	    }
190	    if (flagged) {
191	      await enqueue('mismatch_flag', {
192	        id: `flg_${nanoid(12)}`,
193	        receipt_id: id,
194	        order_item_id: item?.id ?? null,
195	        barcode,
196	        expected: item?.expected_qty ?? null,
197	        received_total: (item?.received_qty ?? 0) + qty,
198	        flagged_at: Date.now(),
199	      });
200	    }
201	    if (item) await addReceivedQty(item.id, qty);
202	
203	    const existing = await findStock(barcode);
204	    if (existing) {
205	      await adjustOnHand(barcode, qty);
206	    } else {
207	      await upsertStock({
208	        barcode,
209	        name: resolvedName,
210	        category: product?.category ?? null,
211	        unit: resolvedUnit,
212	        pack_size: resolvedPackSize,
213	        on_hand: qty,
214	        threshold: 0,
215	      });
216	    }
217	
218	    flushOnce().catch(() => {});
219	
220	    // Track expiry for future alerts
221	    if (expiryDate) {
222	      await trackExpiry({
223	        barcode,
224	        productName: resolvedName,
225	        expiryDate,
226	        qty,
227	        receiptId: id,
228	        performedBy: session?.guardId ?? null,
229	        performedByName: session?.guardName ?? null,
230	      });
231	    }
232	  };
233	
234	  /** Add to order session */
235	  const addToSession = () => {
236	    // Per-pack expiry → N qty=1 batches each with its own date.
237	    // Single-expiry → one batch with the full qty.
238	    const batches = perPackExpiry
239	      ? perPackExpiries.map((d) => ({ qty: 1, expiry: d ? toISO(d) : null }))
240	      : [{ qty, expiry: expiryDate }];
241	    const totalQty = batches.reduce((s, b) => s + b.qty, 0);
242	
243	    orderSession.addItem({
244	      barcode,
245	      productId: productId ?? null,
246	      name: resolvedName,
247	      category: product?.category ?? null,
248	      unit: resolvedUnit,
249	      packSize: resolvedPackSize,
250	      qty: totalQty,
251	      batches,
252	    });
253	    haptic.success();
254	    navigation.navigate('OrderSession');
255	  };
256	
257	  /** Standalone confirm (no active order session) */
258	  const confirmStandalone = async () => {
259	    setSaving(true);
260	    try {
261	      await persistStandalone(false);
262	      haptic.success();
263	      navigation.replace('DeliverySummary', {
264	        items: [{ name: resolvedName, category: product?.category ?? null, qty }],
265	        totalItems: 1,
266	        totalQty: qty,
267	        productName: resolvedName,
268	        qty,
269	        expected: item?.expected_qty ?? null,
270	        flagged: false,
271	      });
272	    } finally {
273	      setSaving(false);
274	    }
275	  };
276	
277	  const flagAndContinueStandalone = async () => {
278	    setSaving(true);
279	    try {
280	      await persistStandalone(true);
281	      haptic.warn();
282	      navigation.replace('DeliverySummary', {
283	        items: [{ name: resolvedName, category: product?.category ?? null, qty }],
284	        totalItems: 1,
285	        totalQty: qty,
286	        productName: resolvedName,
287	        qty,
288	        expected: item?.expected_qty ?? null,
289	        flagged: true,
290	      });
291	    } finally {
292	      setSaving(false);
293	    }
294	  };
295	
296	  const expected = item?.expected_qty ?? null;
297	  const alreadyIn = item?.received_qty ?? 0;
298	  const projected = alreadyIn + qty;
299	  const mismatch = expected !== null && projected > expected;
300	
301	  return (
302	    <KeyboardAvoidingView
303	      behavior={Platform.OS === 'ios' ? 'height' : undefined}
304	      style={{ flex: 1 }}
305	    >
306	      <View style={[styles.safe, { backgroundColor: palette.background }]}>
307	        <AppBar
308	          title={t('receiveItem')}
309	          onBack={() => navigation.goBack()}
310	          trailing={
311	            <View style={{ flexDirection: 'row', alignItems: 'center', gap: spacing.xs }}>
312	              {expected !== null ? (
313	                <StatusPill
314	                  label={`${projected} / ${expected}`}
315	                  tone={mismatch ? 'danger' : projected === expected ? 'success' : 'neutral'}
316	                />
317	              ) : null}
318	              <IconButton Icon={ScanLine} onPress={() => navigation.replace('Scanner')} />
319	            </View>
320	          }
321	        />
322	
323	        <ScrollView
324	          contentContainerStyle={[styles.content, { paddingBottom: spacing.xxxl + kbHeight }]}
325	          keyboardShouldPersistTaps="handled"
326	        >
327	        <Card tone="elevated" padding="xl">
328	          <Text variant="labelLarge" color={palette.onSurfaceVariant}>
329	            {t('product').toUpperCase()}
330	          </Text>
331	          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginTop: spacing.xs, gap: spacing.md }}>
332	            <Text variant="headlineSmall" style={{ flex: 1 }}>
333	              {resolvedName}
334	            </Text>
335	            {packDisplay ? (
336	              <Text variant="titleMedium" color={palette.onSurfaceVariant}>
337	                {packDisplay}
338	              </Text>
339	            ) : null}
340	          </View>
341	          {/* Barcode shown as a chip-style row so guards can confirm
342	              the scan was right at a glance. Bigger font + monospace +
343	              letter-spacing makes it readable without focusing in. */}
344	          <View
345	            style={{
346	              marginTop: spacing.sm,
347	              alignSelf: 'flex-start',
348	              paddingHorizontal: spacing.md,
349	              paddingVertical: spacing.xs,
350	              borderRadius: radius.sm,
351	              borderWidth: 1,
352	              borderColor: palette.outlineVariant,
353	              backgroundColor: palette.surfaceContainerLowest,
354	            }}
355	          >
356	            <Text
357	              variant="titleMedium"
358	              color={palette.onSurface}
359	              style={{
360	                fontFamily: Platform.OS === 'ios' ? 'Menlo' : 'monospace',
361	                letterSpacing: 1.5,
362	              }}
363	            >
364	              {barcode}
365	            </Text>
366	          </View>
367	          {expected !== null ? (
368	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.md }}>
369	              {t('expectedShort')} {expected} · {alreadyIn} {t('alreadyReceived')}
370	            </Text>
371	          ) : (
372	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.md }}>
373	              {t('noMatchingOrder')}
374	            </Text>
375	          )}
376	        </Card>
377	
378	        <View style={styles.qtySection}>
379	          <Text variant="labelLarge" color={palette.onSurfaceVariant} style={{ textAlign: 'center' }}>
380	            {t('quantityReceived').toUpperCase()}
381	          </Text>
382	          <QtyStepper value={qty} onChange={setQty} min={1} />
383	          <View style={styles.quickRow}>
384	            {[5, 10, 20, 50].map((n) => (
385	              <QuickChip key={n} value={n} active={qty === n} onPress={() => setExact(n)} />
386	            ))}
387	          </View>
388	          {mismatch ? (
389	            <View style={{ alignItems: 'center', marginTop: spacing.md }}>
390	              <StatusPill
391	                label={`Over by ${projected - expected!}`}
392	                tone="danger"
393	                Icon={AlertTriangle}
394	              />
395	            </View>
396	          ) : null}
397	        </View>
398	
399	        {/* Expiry Date Section */}
400	        <View style={styles.expirySection}>
401	          <Text variant="labelLarge" color={palette.onSurfaceVariant}>
402	            {t('expiryDate').toUpperCase()}
403	          </Text>
404	
405	          {/* Per-pack toggle. Only useful for multi-quantity scans. */}
406	          {qty > 1 && !noExpiry && (
407	            <Pressable
408	              onPress={() => { setPerPackExpiry((v) => !v); haptic.tap(); }}
409	              style={[styles.noExpiryRow, { marginTop: spacing.sm }]}
410	            >
411	              <View
412	                style={[
413	                  styles.checkbox,
414	                  {
415	                    backgroundColor: perPackExpiry ? palette.primary : 'transparent',
416	                    borderColor: perPackExpiry ? palette.primary : palette.outline,
417	                  },
418	                ]}
419	              >
420	                {perPackExpiry && <Check size={14} color={palette.onPrimary} strokeWidth={3} />}
421	              </View>
422	              <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
423	                {t('perPackExpiry')} ({Math.floor(qty)} {t('packsLabel')})
424	              </Text>
425	            </Pressable>
426	          )}
427	
428	          {!noExpiry && !perPackExpiry && (
429	            <>
430	              <Pressable
431	                onPress={() => setShowPicker(true)}
432	                style={[
433	                  styles.expiryInput,
434	                  {
435	                    backgroundColor: palette.surfaceContainerLowest,
436	                    borderColor: palette.outlineVariant,
437	                    flexDirection: 'row',
438	                    alignItems: 'center',
439	                  },
440	                ]}
441	              >
442	                <Calendar size={20} color={palette.onSurfaceVariant} strokeWidth={2} />
443	                <Text
444	                  variant="bodyLarge"
445	                  color={expiryDateObj ? palette.onSurface : palette.onSurfaceVariant}
446	                  style={{ marginLeft: spacing.sm, flex: 1, letterSpacing: 1 }}
447	                >
448	                  {expiryDateObj ? formatForDisplay(toISO(expiryDateObj)) : t('tapToSelectDate')}
449	                </Text>
450	              </Pressable>
451	              {showPicker && (
452	                <DatePickerModal
453	                  visible={showPicker}
454	                  value={expiryDateObj}
455	                  minimumDate={new Date()}
456	                  onSelect={handlePickerChange}
457	                  onDismiss={() => setShowPicker(false)}
458	                />
459	              )}
460	              <View style={styles.quickRow}>
461	                {QUICK_MONTHS.map((q) => (
462	                  <Pressable
463	                    key={q.label}
464	                    onPress={() => handleQuickMonth(q.months)}
465	                    android_ripple={{ color: palette.outlineVariant }}
466	                    style={[styles.monthChip, { backgroundColor: palette.surfaceContainerLow, borderColor: palette.outlineVariant }]}
467	                  >
468	                    <Text variant="labelLarge" color={palette.onSurface}>
469	                      {q.label}
470	                    </Text>
471	                  </Pressable>
472	                ))}
473	              </View>
474	            </>
475	          )}
476	
477	          {!noExpiry && perPackExpiry && (
478	            <View style={{ marginTop: spacing.sm, gap: spacing.xs }}>
479	              {perPackExpiries.map((d, i) => (
480	                <Pressable
481	                  key={i}
482	                  onPress={() => { setEditingPackIdx(i); setShowPicker(true); }}
483	                  style={[
484	                    styles.expiryInput,
485	                    {
486	                      backgroundColor: palette.surfaceContainerLowest,
487	                      borderColor: palette.outlineVariant,
488	                      flexDirection: 'row',
489	                      alignItems: 'center',
490	                    },
491	                  ]}
492	                >
493	                  <Text variant="labelMedium" color={palette.onSurfaceVariant} style={{ marginRight: spacing.sm, minWidth: 56 }}>
494	                    {t('pack')} {i + 1}
495	                  </Text>
496	                  <Calendar size={18} color={palette.onSurfaceVariant} strokeWidth={2} />
497	                  <Text
498	                    variant="bodyLarge"
499	                    color={d ? palette.onSurface : palette.onSurfaceVariant}
500	                    style={{ marginLeft: spacing.sm, flex: 1, letterSpacing: 1 }}
501	                  >
502	                    {d ? formatForDisplay(toISO(d)) : t('tapToSelectDate')}
503	                  </Text>
504	                </Pressable>
505	              ))}
506	              {showPicker && editingPackIdx != null && (
507	                <DatePickerModal
508	                  visible={showPicker}
509	                  value={perPackExpiries[editingPackIdx]}
510	                  minimumDate={new Date()}
511	                  onSelect={(date) => {
512	                    setPerPackExpiries((prev) => prev.map((p, i) => (i === editingPackIdx ? date : p)));
513	                  }}
514	                  onDismiss={() => { setShowPicker(false); setEditingPackIdx(null); }}
515	                />
516	              )}
517	            </View>
518	          )}
519	
520	          <Pressable
521	            onPress={() => { setNoExpiry(!noExpiry); haptic.tap(); }}
522	            style={styles.noExpiryRow}
523	          >
524	            <View
525	              style={[
526	                styles.checkbox,
527	                {
528	                  backgroundColor: noExpiry ? palette.primary : 'transparent',
529	                  borderColor: noExpiry ? palette.primary : palette.outline,
530	                },
531	              ]}
532	            >
533	              {noExpiry && <Check size={14} color={palette.onPrimary} strokeWidth={3} />}
534	            </View>
535	            <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
536	              {t('noExpiry')}
537	            </Text>
538	          </Pressable>
539	        </View>
540	      </ScrollView>
541	
542	        <View style={[styles.footer, { backgroundColor: palette.surface, borderTopColor: palette.outlineVariant }]}>
543	          {/* Primary action: add to order session */}
544	          <Button
545	            label={t('addToOrder')}
546	            onPress={addToSession}
547	            loading={saving}
548	            size="lg"
549	            fullWidth
550	            leadingIcon={<Check size={22} color={palette.onPrimary} strokeWidth={2.4} />}
551	          />
552	          {/* Secondary: standalone receipt (when not in a multi-scan flow) */}
553	          {!orderSession.isActive && mismatch && (
554	            <Button
555	              label={t('flagAndContinue')}
556	              onPress={flagAndContinueStandalone}
557	              variant="danger"
558	              loading={saving}
559	              size="md"
560	              fullWidth
561	              style={{ marginTop: spacing.sm }}
562	            />
563	          )}
564	          <Button
565	            label={t('cancel')}
566	            variant="text"
567	            onPress={() => navigation.popToTop()}
568	            style={{ marginTop: spacing.sm }}
569	          />
570	        </View>
571	      </View>
572	    </KeyboardAvoidingView>
573	  );
574	}
575	
576	function QuickChip({ value, active, onPress }: { value: number; active: boolean; onPress: () => void }) {
577	  const { palette } = useTheme();
578	  return (
579	    <Pressable
580	      onPress={onPress}
581	      android_ripple={{ color: palette.outlineVariant }}
582	      style={[
583	        styles.quickChip,
