591	        {value}
592	      </Text>
593	    </Pressable>
594	  );
595	}
596	
597	const styles = StyleSheet.create({
598	  safe: { flex: 1 },
599	  content: { padding: spacing.xl, gap: spacing.xl, paddingBottom: spacing.xxxl },
600	  qtySection: { gap: spacing.lg, alignItems: 'stretch' },
601	  quickRow: { flexDirection: 'row', gap: spacing.sm, justifyContent: 'center' },
